import type { CacheManager } from "./CacheManager.js";
import {
  buildAuthMeTag,
  buildAnalyticsDashboardTag,
} from "./cacheKeys.js"; /** * Central registry of mutation → cache tag mappings. * * Every mutation that changes data cached on the backend must be listed here * with the tags it should flush. This file is both documentation and * the single source of truth for invalidation logic. * * Legend: *   ✅  = invalidation implemented *   ❌  = invalidation NOT implemented (gap) *   N/A = mutation does not affect an active backend cache *   👻  = cache tags defined but backend caching not wired yet * * ┌─────────────────────────────────────────────────────────────────────────┐ │                    ACTIVE BACKEND CACHES                                  │ ├──────────────────────────────────────────────────────────────────────────┤ │ Cache key                │ TTL  │ Where cached          │ Applies to       │ │──────────────────────────┼──────┼───────────────────────┼───────────────── │ │ account:{id}:auth-me     │  60s │ AccountService        │ Auth-me profile  │ │ analytics:*              │ 300s │ AnalyticsCache        │ Dashboard stats  │ │ mandapam:*               │  var │ Mandapam pipelines     │ Bookings, etc.  │ └──────────────────────────────────────────────────────────────────────────┘ * * ┌─────────────────────────────────────────────────────────────────────────┐ │                DEFINED BUT NOT WIRED (future targets)                     │ ├──────────────────────────────────────────────────────────────────────────┤ │ profile:{id}             │ 300s │ CacheKeys only 👻    │ Profile detail   │ │ profile-list:user:{id}   │  60s │ CacheKeys only 👻    │ Browse results   │ │ profile-list:admin       │  30s │ CacheKeys only 👻    │ Admin list       │ │ my-profiles:{id}         │ 120s │ CacheKeys only 👻    │ My profiles      │ │ shortlisted:{id}         │  60s │ CacheKeys only 👻    │ Shortlist        │ │ showcase                 │1800s │ CacheKeys only 👻    │ Public showcase  │ │ verification-queue       │  15s │ CacheKeys only 👻    │ Admin queue      │ │ verification-stats       │  60s │ CacheKeys only 👻    │ Admin stats      │ │ membership-caps:{id}     │ 300s │ CacheKeys only 👻    │ Capabilities     │ │ membership-mine:{id}     │ 300s │ CacheKeys only 👻    │ User membership  │ └──────────────────────────────────────────────────────────────────────────┘ */ // ──────────────────────────────────────────────────────────────────────────// 1. Account mutations// ──────────────────────────────────────────────────────────────────────────export const ACCOUNT_MUTATIONS = {  /** changePassword already invalidates auth-me via AccountService */  changePassword: { cache: 'auth-me', tags: (accountId: string) => [buildAuthMeTag(accountId)], status: '✅' as const },  /** updateProfile lazy-refreshes via getProfile() — no explicit invalidate needed */  updateProfile: { cache: 'auth-me', tags: (accountId: string) => [buildAuthMeTag(accountId)], status: '✅' as const },  /** Suspend: account state changes, auth-me doesn't include currentState today but flush for consistency */  suspendAccount: { cache: 'auth-me', tags: (accountId: string) => [buildAuthMeTag(accountId)], status: '✅' as const },  /** Restore: same reasoning as suspend */  restoreAccount: { cache: 'auth-me', tags: (accountId: string) => [buildAuthMeTag(accountId)], status: '✅' as const },  /** Logout/logoutAll: session is revoked but auth-me data unchanged → no flush needed */  logout: { cache: 'auth-me', tags: (accountId: string) => [buildAuthMeTag(accountId)], status: 'N/A' as const },  /** Reset password: tokenVersion incremented → auth-me doesn't include it → N/A */  resetPassword: { cache: 'auth-me', tags: (accountId: string) => [buildAuthMeTag(accountId)], status: 'N/A' as const },} as const;// ──────────────────────────────────────────────────────────────────────────// 2. Analytics mutations// ──────────────────────────────────────────────────────────────────────────export const ANALYTICS_MUTATIONS = {  /**   * Profile approve/reject/update/archive change the underlying data that   * analytics aggregates. The 300s TTL provides acceptable staleness.   * If real-time accuracy is needed, flush buildAnalyticsDashboardTag() here.   */  profileStatusChange: { cache: 'analytics-dashboard', tags: () => [buildAnalyticsDashboardTag()], status: 'N/A (TTL sufficient)' as const },} as const;// ──────────────────────────────────────────────────────────────────────────// 3. Mandapam mutations (all handled via pipeline — validated during Sprint 0)// ──────────────────────────────────────────────────────────────────────────export const MANDAPAM_MUTATIONS = {  bookingCreatePipeline:      { status: '✅' as const },  bookingStatusPipeline:      { status: '✅' as const },  bookingSettlementPipeline:  { status: '✅' as const },  financialTransactionPipeline: { status: '✅' as const },  bookingChargePipeline:      { status: '✅' as const },  bookingAddonPipeline:       { status: '✅' as const },  packageUpdatePipeline:      { status: '✅' as const },  packageDeleteFunctionPipeline: { status: '✅' as const },  catalogEntityPipeline:      { status: '✅' as const },} as const;// ──────────────────────────────────────────────────────────────────────────// 4. Profile mutations (target future cache wiring)// ──────────────────────────────────────────────────────────────────────────export const PROFILE_MUTATIONS = {  /**   * These mutations will need invalidation once backend profile caching   * is wired. Currently handled by frontend React Query cache only.   */  createProfile:     { cache: 'my-profiles / profile-list', tags: () => [], status: '👻 (future)' as const },  updateProfile:     { cache: 'profile:{id}', tags: (profileId: string) => [], status: '👻 (future)' as const },  deleteDraft:       { cache: 'my-profiles', tags: () => [], status: '👻 (future)' as const },  toggleShortlist:   { cache: 'shortlisted', tags: () => [], status: '👻 (future)' as const },  saveDraft:         { cache: 'my-profiles', tags: () => [], status: '👻 (future)' as const },} as const;// ──────────────────────────────────────────────────────────────────────────// 5. Verification mutations (target future cache wiring)// ──────────────────────────────────────────────────────────────────────────export const VERIFICATION_MUTATIONS = {  approveProfile: { cache: 'verification-queue / verification-stats', status: '👻 (future)' as const },  rejectProfile:  { cache: 'verification-queue / verification-stats', status: '👻 (future)' as const },} as const;// ──────────────────────────────────────────────────────────────────────────// 6. Membership mutations (target future cache wiring)// ──────────────────────────────────────────────────────────────────────────export const MEMBERSHIP_MUTATIONS = {  updatePlan:         { cache: 'membership-plans', status: '👻 (future)' as const },  updateSetting:      { cache: 'membership-settings', status: '👻 (future)' as const },  assignSubscription: { cache: 'membership-mine / membership-caps', status: '👻 (future)' as const },  cancelSubscription: { cache: 'membership-mine / membership-caps', status: '👻 (future)' as const },} as const;// ──────────────────────────────────────────────────────────────────────────// 7. Admin mutations// ──────────────────────────────────────────────────────────────────────────export const ADMIN_MUTATIONS = {  /**   * Admin profile operations: once admin profile list caching is wired,   * mutations here should flush profile-list:admin tags.   */  adminUpdateProfile:  { cache: 'profile-list:admin', status: '👻 (future)' as const },  adminArchiveProfile: { cache: 'profile-list:admin', status: '👻 (future)' as const },  adminRestoreProfile: { cache: 'profile-list:admin', status: '👻 (future)' as const },  adminDeleteProfile:  { cache: 'profile-list:admin', status: '👻 (future)' as const },} as const;/** * Global summary for quick reference. * Run this to print the registry at startup in development. */export function printRegistrySummary(): string {  const active = [    ['Account.changePassword', '✅'],    ['Account.updateProfile', '✅ (lazy-refresh)'],    ['AdminAccount.suspendAccount', '✅'],    ['AdminAccount.restoreAccount', '✅'],  ];  const ghost = [    ['Profile mutations (5)', '👻'],    ['Verification mutations (2)', '👻'],    ['Membership mutations (4)', '👻'],    ['Admin profile mutations (4)', '👻'],  ];  return [    '=== Cache Invalidation Registry ===',    '',    'Active (cached + invalidated):',    ...active.map(([k, v]) => `  ${v} ${k}`),    '',    'Future (cache not wired yet):',    ...ghost.map(([k, v]) => `  ${v} ${k}`),    '',    `Total: ${active.length} active, ${ghost.reduce((s, [, c]) => s + parseInt(c) || 0, 0)} future`,  ].join('\n');}/** * Flush cache for a mutation that affects account auth-me. * Convenience wrapper used by controllers that have CacheManager. */export async function flushAuthMe(cacheManager: CacheManager, accountId: string): Promise<void> {  await cacheManager.flushTags([buildAuthMeTag(accountId)]);}
